import java.util.Arrays;
public class FractionalKnapsack {
    static class Item { int weight, value; double ratio; Item(int w,int v){weight=w;value=v;ratio=(double)v/w;} }
    public double maxValue(int W, int[] wt, int[] val) {
        Item[] items = new Item[wt.length];
        for (int i = 0; i < wt.length; i++) items[i] = new Item(wt[i], val[i]);
        Arrays.sort(items, (a,b) -> Double.compare(b.ratio, a.ratio));
        double total = 0;
        for (Item item : items) {
            if (W >= item.weight) { total += item.value; W -= item.weight; }
            else { total += item.ratio * W; break; }
        }
        return total;
    }
}

