#include <stdio.h>
#include <stdlib.h>
typedef struct {
    int w, v;
    double r;
} Item;
int cmp(const void*a, const void*b) {
    return ((Item*)b)->r>((Item*)a)->r?1:-1;
}
double fracKnapsack(int W, int wt[], int v[], int n) {
    Item it[n];
    for (int i=0; i<n; i++) {
        it[i].w=wt[i];
        it[i].v=v[i];
        it[i].r=(double)v[i]/wt[i];
    }
    qsort(it, n, sizeof(Item), cmp);
    double tot=0;
    for (int i=0; i<n&&W>0; i++) {
        if (W>=it[i].w) {
            tot+=it[i].v;
            W-=it[i].w;
        }else {
            tot+=it[i].r*W;
            W=0;
        }
    }
    return tot;
}

