def fractional_knapsack(items, capacity):
    items.sort(key=lambda it: it[1] / it[0], reverse=True)  # by value/weight
    total = 0.0
    for weight, value in items:
        if capacity >= weight:
            capacity -= weight
            total += value
        else:
            total += value * capacity / weight
            break
    return total

